let state={};try{state=JSON.parse(localStorage.getItem('cw_state_v3')||'{}')}catch(e){state={}};state.cart??=[];state.wishlist??=[];state.bookings??=[];state.selected??=1;state.qty??=2;state.time??='12:00 PM';state.date??='2026-11-21';state.tab??='Overview';state.filter??='All';state.query??='';state.max??=500;state.minRating??=0;state.sort??='featured';state.bookingTab??='Upcoming';state.paymentMethod??='mada';state.promoCode??='';state.walletBalance??=50;state.bills??=[];state.split??=false;state.resched=null;state.cart=state.cart.filter(c=>items.some(x=>x.id===c.id));state.wishlist=state.wishlist.filter(id=>items.some(x=>x.id===id));const PAGE_FILES={home:'index.html',workshops:'workshops.html',categories:'categories.html',about:'about.html',contact:'contact.html',partner:'partner.html',privacy:'privacy.html',accessibility:'accessibility.html',login:'login.html',register:'register.html',profile:'profile.html',wishlist:'wishlist.html',cart:'cart.html',checkout:'checkout.html',booking:'booking.html',bookings:'bookings.html',confirmation:'confirmation.html',payment:'payment.html',ticket:'ticket.html',detail:'detail.html',search:'search.html'};
